import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Success page and redirect","description":"Define what happens after a form is submitted.","frontmatter":{"title":"Success page and redirect","description":"Define what happens after a form is submitted."},"headers":[],"relativePath":"en/formulare/erfolgsseite.md","filePath":"en/formulare/erfolgsseite.md","lastUpdated":1787319236000}'),i={name:"en/formulare/erfolgsseite.md"};function s(n,t,d,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="success-page-and-redirect" tabindex="-1">Success page and redirect <a class="header-anchor" href="#success-page-and-redirect" aria-label="Permalink to &quot;Success page and redirect&quot;">​</a></h1><p>The <strong>Success page</strong> section in the <em>Layout</em> tab determines what people see after submitting.</p><h2 id="confirmation-text" tabindex="-1">Confirmation text <a class="header-anchor" href="#confirmation-text" aria-label="Permalink to &quot;Confirmation text&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td><em>Thank you!</em></td></tr><tr><td><strong>Message</strong></td><td><em>Your response has been received.</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Say what happens next</p><p>The default only confirms receipt. It&#39;s more useful to say what happens next: &quot;We&#39;ll get back to you within two business days.&quot; or &quot;You&#39;ll receive a confirmation email shortly.&quot;</p><p>This noticeably reduces follow-up questions — especially when a <a href="/en/flows/was-ist-ein-flow">Flow</a> sends a confirmation email in the background.</p></div><h2 id="action-after-submitting" tabindex="-1">Action after submitting <a class="header-anchor" href="#action-after-submitting" aria-label="Permalink to &quot;Action after submitting&quot;">​</a></h2><p>Three options:</p><table tabindex="0"><thead><tr><th>Action</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>No action</strong></td><td>The success message stays as-is</td></tr><tr><td><strong>Fill out again</strong></td><td>A button reopens the form</td></tr><tr><td><strong>Redirect to website</strong></td><td>Redirects to a specified <strong>website</strong></td></tr></tbody></table><h3 id="fill-out-again" tabindex="-1">Fill out again <a class="header-anchor" href="#fill-out-again" aria-label="Permalink to &quot;Fill out again&quot;">​</a></h3><p>For cases where the same person submits several entries in a row — inventory counts, capturing multiple items, registering several people.</p><p>You set the button label via <strong>Text &#39;Send another form&#39;</strong>; by default it reads <em>Send another response</em> for the person filling it out.</p><h3 id="redirect-to-website" tabindex="-1">Redirect to website <a class="header-anchor" href="#redirect-to-website" aria-label="Permalink to &quot;Redirect to website&quot;">​</a></h3><p>Redirects to an address of your choice — your website, a thank-you page, or an appointment booking page.</p><p>The field is called <strong>Website</strong>, with the placeholder <code>https://www...</code>.</p><div class="warning custom-block"><p class="custom-block-title">Plan-dependent</p><p>The redirect option isn&#39;t available on every plan.</p></div><h2 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h2><p>For <em>Fill out again</em> and <em>Redirect to website</em>, you also set the timing:</p><table tabindex="0"><thead><tr><th>Option</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Click button</strong></td><td>The person decides for themselves</td></tr><tr><td><strong>Immediately after submitting</strong></td><td>Right away, without confirmation</td></tr><tr><td><strong>after 5 seconds</strong></td><td>The success message stays visible briefly</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">&quot;Immediately after submitting&quot; skips the confirmation</p><p>People then see <strong>no</strong> feedback that anything arrived — they land directly on the target page. This is confusing and leads to duplicate submissions.</p><p><strong>After 5 seconds</strong> is almost always the better choice: the confirmation gets read, and the redirect still happens automatically.</p></div><div class="tip custom-block"><p class="custom-block-title">The button text says where it leads</p><p>With <em>Click button</em>, you can choose the label freely. &quot;Go to appointment booking&quot; is more helpful than &quot;Next&quot; — the person knows what to expect.</p></div><h2 id="product-notice" tabindex="-1">Product notice <a class="header-anchor" href="#product-notice" aria-label="Permalink to &quot;Product notice&quot;">​</a></h2><p><strong>Hide product notice</strong> removes the notice <em>Create your own free form with …</em>. Plan-dependent.</p><h2 id="interaction-with-other-settings" tabindex="-1">Interaction with other settings <a class="header-anchor" href="#interaction-with-other-settings" aria-label="Permalink to &quot;Interaction with other settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Interaction</th></tr></thead><tbody><tr><td><a href="/en/formulare/speichern-und-fortsetzen">Save to continue later</a></td><td>Its own confirmation, <em>Form has been saved!</em></td></tr><tr><td><strong>Auto-submit</strong></td><td>The success page appears immediately on load</td></tr><tr><td><strong>Hide submit button</strong></td><td>Without submitting, the success page is never reached</td></tr><tr><td><a href="/en/formulare/mehrsprachig">Multilingual support</a></td><td>Title, message, and button text can be translated</td></tr></tbody></table><h2 id="what-else-people-filling-it-out-see" tabindex="-1">What else people filling it out see <a class="header-anchor" href="#what-else-people-filling-it-out-see" aria-label="Permalink to &quot;What else people filling it out see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Text</th></tr></thead><tbody><tr><td>Submit</td><td><em>Submit</em></td></tr><tr><td>Back to form</td><td><em>Back to form</em></td></tr><tr><td>On an error</td><td><em>Oops - Error</em></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/formular-erstellen">Creating a form</a></li><li><a href="/en/formulare/speichern-und-fortsetzen">Save and continue later</a></li><li><a href="/en/formulare/gestaltung">Design</a></li></ul>',28)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
